function inspect(raw) {
const t=raw.content.filter(x=>x.type==="text").map(x=>x.text).join("\n");
const cols="ABCDEFGHJ";const b={};
for(const line of t.split("\n")) { const m=line.match(/^\s*([1-9])\s+([XO.](?:\s+[XO.]){8})\s+[1-9]\s*$/);if(m) m[2].split(/\s+/).forEach((v,i)=>b[cols[i]+m[1]]=v); }
