const seen=new Set(),groups=[],regions=[];
for(const p of Object.keys(b)) {if(seen.has(p))continue;const color=b[p],q=[p],stones=[],lib=new Set(),boundary=new Set();seen.add(p);while(q.length){const a=q.pop();stones.push(a);for(const n of adjacent(a)){if(b[n]===color&&!seen.has(n)){seen.add(n);q.push(n);}else if(b[n]!==color){if(b[n]===".")lib.add(n);else boundary.add(n);}}}
if(color===".")regions.push({points:stones.sort(),boundary:[...boundary].sort(),owners:[...new Set([...boundary].map(p=>b[p]))].sort()});else groups.push({color,stones:stones.sort(),liberties:[...lib].sort()});}
const counts={X:0,O:0,empty:0};Object.values(b).forEach(v=>v==="."?counts.empty++:counts[v]++);
const area={X:counts.X,O:counts.O,neutral:0};for(const r of regions)if(r.owners.length===1)area[r.owners[0]]+=r.points.length;else area.neutral+=r.points.length;
