const group=p=>{const color=b[p],seen=new Set([p]),q=[p],libs=new Set();while(q.length){for(const n of adjacent(q.pop())){if(b[n]===".")libs.add(n);else if(b[n]===color&&!seen.has(n)){seen.add(n);q.push(n);}}}return{stones:[...seen],liberties:[...libs]};};
